import{_ as s,o as a,c as e,a7 as t}from"./chunks/framework.DUCm5Bu5.js";const c=JSON.parse('{"title":"快速开始","description":"从已构建的检出启动隔离的本地服务器，并确认它正在运行。","frontmatter":{"title":"快速开始","description":"从已构建的检出启动隔离的本地服务器，并确认它正在运行。","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),l={name:"getting-started/quickstart.md"};function h(n,i,p,o,d,r){return a(),e("div",null,[...i[0]||(i[0]=[t('<p>本页使用你在<a href="./installation">安装</a>中构建好的检出，启动一个使用内存持久化的本地隔离服务器。它先以无游戏监听的管理 profile <code>management</code> 完成第一次成功检查，然后说明 <code>kr-812</code> 这类游戏 profile 有何不同，以及这些检查能证明什么、不能证明什么。</p><p><strong>本页适合：</strong> 已完成源码构建、希望在几分钟内跑起本地服务器的读者。</p><h2 id="你将得到什么" tabindex="-1">你将得到什么 <a class="header-anchor" href="#你将得到什么" aria-label="Permalink to &quot;你将得到什么&quot;">​</a></h2><p>一个可以安全启动和停止的本地服务器进程，使用内存持久化，不连接任何真实数据库。进程退出后账号与进度都会重置。它不是可完整游玩的服务器，也不能证明游戏客户端可用。</p><p><code>management</code> profile 只启动管理 API 与 WebUI，没有游戏或中继监听，因此不需要客户端数据即可运行。<code>kr-812</code> 这类游戏 profile 还需要该版本对应的本地客户端数据，而仓库不包含这些数据。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><ul><li>已完成<a href="./installation">安装</a>：解决方案以零警告构建成功，且构建输出存在。</li><li>终端位于仓库根目录；本页所有命令都在此执行。</li><li>.NET 10 SDK 可用：<code>dotnet --version</code> 输出 10.x 版本。</li><li>本地检查补丁存在。在 PowerShell 中用 <code>Test-Path tools/local-checks/isolated-memory.patch.yaml</code> 检查，或在 POSIX shell 中用 <code>test -f tools/local-checks/isolated-memory.patch.yaml</code> 检查。</li><li>下一步会创建 <code>.env</code> 文件。</li><li>可选：如果本次要启动 <code>kr-812</code>，匹配的客户端数据已在 <code>client-data/kr-812/data</code> 或 <code>client-data/kr-812/dataraw</code> 下。</li></ul><h2 id="准备本地环境变量文件" tabindex="-1">准备本地环境变量文件 <a class="header-anchor" href="#准备本地环境变量文件" aria-label="Permalink to &quot;准备本地环境变量文件&quot;">​</a></h2><p>profile 在组合时就会插入环境变量，此时任何补丁都还没有停用服务。因此即使是内存检查，也必须存在本地的 MySQL 密码变量。</p><h3 id="_1-复制示例文件" tabindex="-1">1. 复制示例文件 <a class="header-anchor" href="#_1-复制示例文件" aria-label="Permalink to &quot;1. 复制示例文件&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .env.example .env</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p><code>.env</code> 被 Git 忽略，绝不要提交。</p><h3 id="_2-设置临时密码" tabindex="-1">2. 设置临时密码 <a class="header-anchor" href="#_2-设置临时密码" aria-label="Permalink to &quot;2. 设置临时密码&quot;">​</a></h3><p>打开 <code>.env</code>，把 <code>BFF_MYSQL_PASSWORD</code> 设为非空的临时值，例如 <code>isolated-check-only</code>。<code>persistence.mysql</code> 行读取没有默认值的 <code>${BFF_MYSQL_PASSWORD}</code>，变量缺失时组合会失败；隔离内存补丁只在组合之后才停用该行。本地检查不要使用真实数据库凭据，真实凭据只用于刻意配置的部署。</p><p><strong>检查是否成功：</strong> <code>.env</code> 存在（<code>Test-Path .env</code> 输出 <code>True</code>），且 <code>BFF_MYSQL_PASSWORD</code> 行非空。不要把该文件或其值粘贴到聊天或问题中。</p><h2 id="找到-profile" tabindex="-1">找到 profile <a class="header-anchor" href="#找到-profile" aria-label="Permalink to &quot;找到 profile&quot;">​</a></h2><p>profile 指定一个客户端版本，并组合该版本使用的插件行。它的 id 是 <code>&lt;region&gt;-&lt;wire version&gt;</code>，其中数字是客户端的 <code>ClientVersion_Major</code>，不是可执行文件的文件版本。<code>management</code> 是仅管理用途的 profile；<code>setup</code> 是首次运行向导。</p><h3 id="_1-列出打包的-profile" tabindex="-1">1. 列出打包的 profile <a class="header-anchor" href="#_1-列出打包的-profile" aria-label="Permalink to &quot;1. 列出打包的 profile&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiles list</span></span></code></pre></div><p>命令为每个 profile 输出一行：id 与描述。本版本列出 19 个。其中两行比较有用：<code>management</code>（“Administration and durable storage only; no game or relay ports.”）和 <code>kr-812</code>（“Korean 2015 client build, ClientVersion_Major 812, resource patch 458.”）。</p><p>列出某个 profile 不代表该版本的全部玩法都已实现；不同 profile 可用的功能与所需数据不同。</p><h3 id="_2-列出发现的插件" tabindex="-1">2. 列出发现的插件 <a class="header-anchor" href="#_2-列出发现的插件" aria-label="Permalink to &quot;2. 列出发现的插件&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> plugins list</span></span></code></pre></div><p>命令为每个插件定义输出一行：插件 id、版本、支持的客户端版本以及加载来源。这就是 Host 可以挂载到 profile 中的实现集合。</p><p><strong>检查是否成功：</strong> 两条命令都成功退出并输出内容，没有 profile 或插件扫描错误。</p><h2 id="检查生效的配置" tabindex="-1">检查生效的配置 <a class="header-anchor" href="#检查生效的配置" aria-label="Permalink to &quot;检查生效的配置&quot;">​</a></h2><p>用本地检查补丁组合 <code>kr-812</code>，在不启动任何东西的情况下打印结果：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dump</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config</span></span></code></pre></div><p>命令以 YAML 输出生效的行列表，并以退出码 0 结束。请在输出中查找以下行：</p><ul><li><code>id: persistence.mysql</code> 后面跟着 <code>disabled: true</code>；</li><li><code>id: persistence.memory</code> 没有 <code>disabled: true</code>，即已启用；</li><li><code>id: clientdata</code> 显示 <code>kr-812</code> 解析后的 <code>data_directory</code> 与 <code>raw_directory</code>。</li></ul><p>隔离补丁最后应用，因此会覆盖开发者 <code>.env</code> 或 <code>local.patch.yaml</code> 中把 MySQL 指向真实数据库的设置。转储会在任何插件激活之前结束，因此只能证明组合与校验，不能证明 profile 能启动。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>当补丁启用 MySQL 时，转储可能包含插值后的值，包括凭据。请把它视为敏感内容。</p></div><h2 id="启动服务器" tabindex="-1">启动服务器 <a class="header-anchor" href="#启动服务器" aria-label="Permalink to &quot;启动服务器&quot;">​</a></h2><h3 id="_1-启动无游戏的本地服务器" tabindex="-1">1. 启动无游戏的本地服务器 <a class="header-anchor" href="#_1-启动无游戏的本地服务器" aria-label="Permalink to &quot;1. 启动无游戏的本地服务器&quot;">​</a></h3><p>在仓库根目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile management </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>如果仓库根目录存在 <code>.env</code>，第一行是 <code>Loaded unset variables from &lt;path&gt;.</code>。随后服务器会打印管理监听地址、WebUI 地址和活动行数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Row &#39;admin.http&#39; admin API listening on 127.0.0.1:8080.</span></span>\n<span class="line"><span>WebUI: http://127.0.0.1:8080/</span></span>\n<span class="line"><span>Server started with &lt;count&gt; active row(s).</span></span></code></pre></div><p><code>&lt;count&gt;</code> 是 Host 打印的活动行数量，不是固定数字。<code>management</code> 没有游戏或中继端口。它的管理 API 基础地址是 <code>http://127.0.0.1:8080</code>，来自 <code>profiles/bundles/core.yaml</code> 中的 <code>admin.http</code> 行（<code>${BFF_ADMIN_HOST:-127.0.0.1}:${BFF_ADMIN_PORT:-8080}</code>）。进程会一直保持在前台，直到你停止它。</p><h3 id="_2-改为启动游戏-profile-需要客户端数据" tabindex="-1">2. 改为启动游戏 profile（需要客户端数据） <a class="header-anchor" href="#_2-改为启动游戏-profile-需要客户端数据" aria-label="Permalink to &quot;2. 改为启动游戏 profile（需要客户端数据）&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml</span></span></code></pre></div><p>游戏 profile 需要匹配的客户端数据。缺少数据时，<code>clientdata</code> 行会失败，启动会以类似下面的消息停止：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clientdata: neither data_directory &#39;&lt;working-directory&gt;/client-data/kr-812/data&#39; nor raw_directory &#39;&lt;working-directory&gt;/client-data/kr-812/dataraw&#39; exists. Provision the configured client-data directories before enabling this row.</span></span></code></pre></div><p>请提供数据，或按<a href="./installation">安装</a>所述通过安装向导导入，然后重新启动该 profile。数据就位后，<code>kr-812</code> 会在 <code>${BFF_BIND_HOST:-0.0.0.0}:${LEGACY_PORT}</code> 上绑定游戏监听，因为 <code>profiles/kr-812/profile.yaml</code> 把 <code>LEGACY_PORT</code> 设为 <code>${KR_812_GAME_PORT:-7110}</code>，所以实际是 <code>0.0.0.0:7110</code>。旧版（legacy）版本没有中继监听。管理 API 仍是 <code>127.0.0.1:8080</code>。</p><p><strong>检查是否成功：</strong> 进程保持在前台，打印上面三行启动信息，且没有以激活错误退出。</p><h2 id="确认它正在运行" tabindex="-1">确认它正在运行 <a class="header-anchor" href="#确认它正在运行" aria-label="Permalink to &quot;确认它正在运行&quot;">​</a></h2><h3 id="_1-检查健康检查端点" tabindex="-1">1. 检查健康检查端点 <a class="header-anchor" href="#_1-检查健康检查端点" aria-label="Permalink to &quot;1. 检查健康检查端点&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">health</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span></code></pre></div><p>响应包含 <code>status</code> = <code>ok</code> 以及 UTC 时间戳。<code>/health</code> 始终无需登录。</p><h3 id="_2-检查运行时实例" tabindex="-1">2. 检查运行时实例 <a class="header-anchor" href="#_2-检查运行时实例" aria-label="Permalink to &quot;2. 检查运行时实例&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugins </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-Table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rowId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> state</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/plugins</span></span></code></pre></div><p><code>/api/plugins</code> 返回正在运行的插件行。每一项包含 <code>rowId</code>、<code>plugin</code>、<code>source</code>、<code>state</code> 和 <code>error</code>。请查找 <code>state</code> = <code>Active</code> 且 <code>error</code> 为空的行；<code>Failed</code> 或 <code>Pending</code> 行会在 <code>error</code> 中给出诊断信息。</p><p>以 <code>run --profile</code> 启动的服务器访问 <code>/api</code> 无需登录，并且只在回环地址上监听。不带参数启动的服务器（首次安装）会要求你创建的管理员账号；其会话是浏览器 Cookie，因此请通过 WebUI 进行这些操作。</p><h3 id="_3-打开-webui" tabindex="-1">3. 打开 WebUI <a class="header-anchor" href="#_3-打开-webui" aria-label="Permalink to &quot;3. 打开 WebUI&quot;">​</a></h3><p>在浏览器中打开 <code>http://127.0.0.1:8080/</code>。management profile 会提供管理界面。</p><p><strong>检查是否成功：</strong> 健康检查返回 <code>ok</code>，实例列表显示活动行，且 WebUI 可以加载。这些检查证明 Host 及其管理 API 正在运行；它们不能证明游戏客户端可以连接。</p><h2 id="停止服务器" tabindex="-1">停止服务器 <a class="header-anchor" href="#停止服务器" aria-label="Permalink to &quot;停止服务器&quot;">​</a></h2><p>在运行服务器的终端按 Ctrl+C。控制台会打印 <code>Shutdown complete.</code>，随后进程退出。内存中的账号与进度随进程一起丢弃；对本地检查来说停止总是安全的，因为没有任何持久数据被改动。</p><p>如果希望数据在重启后保留，请按<a href="./../guides/configuration">服务器配置</a>把持久化切换到 SQLite 或 MySQL。隔离内存补丁只用于本地检查。</p><h2 id="这不能证明什么" tabindex="-1">这不能证明什么 <a class="header-anchor" href="#这不能证明什么" aria-label="Permalink to &quot;这不能证明什么&quot;">​</a></h2><ul><li>没有游戏客户端登录，也没有验证任何玩法或数据包兼容性。</li><li>management profile 没有游戏或中继监听，因此完全没有客户端流量。</li><li>配置检查或自动检查通过不等于真实客户端验收；请另行用真实客户端验证目标登录与游戏流程。</li></ul><h2 id="出现问题时" tabindex="-1">出现问题时 <a class="header-anchor" href="#出现问题时" aria-label="Permalink to &quot;出现问题时&quot;">​</a></h2><ul><li><strong><code>environment variable &#39;BFF_MYSQL_PASSWORD&#39; is not set and has no default</code>：</strong> <code>.env</code> 文件缺失、没有在仓库根目录找到，或没有设置该变量。复制 <code>.env.example</code> 并设置一个临时值。</li><li><strong>管理端口已被占用：</strong> 启动会在监听行失败。请在 <code>.env</code> 中设置 <code>BFF_ADMIN_PORT</code>，或停止占用 8080 的进程。</li><li><strong>游戏端口已被占用：</strong> 请在 <code>.env</code> 中设置 <code>KR_812_GAME_PORT</code>，或停止占用 7110 的进程。</li><li><strong><code>kr-812</code> 因 <code>clientdata</code> 失败：</strong> 参见上面的客户端数据消息；该版本的数据必须存在，profile 才能启动。</li><li><strong><code>Server startup did not converge</code>：</strong> 消息会列出每个未激活的行及其状态与诊断。先阅读第一个 <code>Failed</code> 或 <code>Pending</code> 行并修复其原因。</li></ul><p>更多情况见<a href="./../guides/troubleshooting">疑难排查</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读<a href="./../guides/configuration">服务器配置</a>，了解持久化、端口、profile 与环境变量；然后阅读<a href="./../guides/plugins">插件</a>，了解插件行的工作方式以及如何挂载自己的插件。配套启动器如何安装客户端并连接服务器，见<a href="./../guides/launcher">启动器</a>。</p>',75)])])}const g=s(l,[["render",h]]);export{c as __pageData,g as default};
